/**
 * Open-source Piper TTS prompt catalog for E3 IVR.
 *
 * Clips live under `public/ivr/{en,ar}/` and are generated by
 * `npm run ivr:generate-audio` (Piper en_US-lessac + ar_JO-kareem).
 * Telnyx Play requires absolute HTTPS — use {@link resolvePublicMediaUrl}.
 *
 * IMPORTANT: Piper `/ivr/` Play is **off by default** (`IVR_OSS_PLAY_ENABLED`).
 * TeXML emits Play-only (no Say fallback); Call Control treats a successful
 * gather_using_audio as done even when the clip is silent/unplayable.
 * Until clips are proven Telnyx-safe (prefer 8 kHz mono WAV/MP3), keep the
 * flag off so Joanna / Fatima TTS always speaks.
 *
 * Arabic is Jordanian (ar_JO), the best CPU Piper dialect available —
 * clearer than silent/manual-only, not true Qatari. Human uploads still win.
 */

import {
  E3_CENTER_GREETING_AR,
  E3_CENTER_GREETING_EN,
  E3_LANG_GREETING_AR,
  E3_LANG_GREETING_EN,
  E3_SERVICE_GREETING_AR,
  E3_SERVICE_GREETING_EN,
} from "./e3-ivr-prompt";
import {
  CONNECTING_TO_AGENT_AR,
  CONNECTING_TO_AGENT_EN,
  RECORDING_DISCLOSURE_AR,
  RECORDING_DISCLOSURE_EN,
} from "./recording-disclosure";

export type IvrOssLang = "en" | "ar";

export type IvrOssPromptId =
  | "language-menu"
  | "center-menu"
  | "service-menu"
  | "bridge-connecting";

export type IvrOssPrompt = {
  id: IvrOssPromptId;
  /** Relative public path, e.g. `/ivr/en/language-menu.mp3`. */
  path: string;
  text: string;
  lang: IvrOssLang;
};

const EN_BRIDGE = `${RECORDING_DISCLOSURE_EN} ${CONNECTING_TO_AGENT_EN}`;
const AR_BRIDGE = `${RECORDING_DISCLOSURE_AR} ${CONNECTING_TO_AGENT_AR}`;

/** All standard E3 IVR clips (EN + AR). */
export const IVR_OSS_PROMPTS: readonly IvrOssPrompt[] = [
  {
    id: "language-menu",
    lang: "en",
    path: "/ivr/en/language-menu.mp3",
    text: E3_LANG_GREETING_EN,
  },
  {
    id: "language-menu",
    lang: "ar",
    path: "/ivr/ar/language-menu.mp3",
    text: E3_LANG_GREETING_AR,
  },
  {
    id: "center-menu",
    lang: "en",
    path: "/ivr/en/center-menu.mp3",
    text: E3_CENTER_GREETING_EN,
  },
  {
    id: "center-menu",
    lang: "ar",
    path: "/ivr/ar/center-menu.mp3",
    text: E3_CENTER_GREETING_AR,
  },
  {
    id: "service-menu",
    lang: "en",
    path: "/ivr/en/service-menu.mp3",
    text: E3_SERVICE_GREETING_EN,
  },
  {
    id: "service-menu",
    lang: "ar",
    path: "/ivr/ar/service-menu.mp3",
    text: E3_SERVICE_GREETING_AR,
  },
  {
    id: "bridge-connecting",
    lang: "en",
    path: "/ivr/en/bridge-connecting.mp3",
    text: EN_BRIDGE,
  },
  {
    id: "bridge-connecting",
    lang: "ar",
    path: "/ivr/ar/bridge-connecting.mp3",
    text: AR_BRIDGE,
  },
] as const;

export const DEFAULT_IVR_OSS_BRIDGE_EN = "/ivr/en/bridge-connecting.mp3";
export const DEFAULT_IVR_OSS_BRIDGE_AR = "/ivr/ar/bridge-connecting.mp3";

export function ivrOssPromptPath(id: IvrOssPromptId, lang: IvrOssLang): string {
  const hit = IVR_OSS_PROMPTS.find((p) => p.id === id && p.lang === lang);
  return hit?.path ?? "";
}

/**
 * Opt-in for Piper `/ivr/*` Play URLs. Default off — TTS must never go silent.
 * Set `IVR_OSS_PLAY_ENABLED=1` only after Telnyx Play is verified on a test call.
 */
export function ivrOssPlayEnabled(): boolean {
  const v = process.env.IVR_OSS_PLAY_ENABLED?.trim().toLowerCase();
  return v === "1" || v === "true" || v === "yes";
}

/** True for app-relative or absolute URLs under `/ivr/` (Piper OSS clips). */
export function isIvrOssMediaPath(url: string | null | undefined): boolean {
  const raw = (url ?? "").trim();
  if (!raw) return false;
  if (/^https?:\/\//i.test(raw)) {
    try {
      return /^\/ivr\//i.test(new URL(raw).pathname);
    } catch {
      return /\/ivr\//i.test(raw);
    }
  }
  return /^\/?ivr\//i.test(raw);
}

/** App origin used for Telnyx absolute Play URLs. */
export function publicAppOrigin(): string {
  const fromEnv =
    process.env.NEXT_PUBLIC_APP_URL?.trim() ||
    process.env.APP_URL?.trim() ||
    (process.env.VERCEL_URL?.trim() ? `https://${process.env.VERCEL_URL.trim()}` : "");
  return (fromEnv || "https://e3fec.vercel.app").replace(/\/$/, "");
}

/**
 * Turn a relative `/ivr/...` (or any app-relative) path into an absolute HTTPS URL.
 * Absolute http(s) URLs are returned unchanged. Empty stays empty.
 *
 * When {@link ivrOssPlayEnabled} is false, `/ivr/` Piper paths resolve to empty
 * so callers fall back to TTS instead of silent Play.
 */
export function resolvePublicMediaUrl(
  url: string | null | undefined,
  origin = publicAppOrigin(),
): string {
  const raw = (url ?? "").trim();
  if (!raw) return "";
  // Block Piper OSS clips unless explicitly re-enabled (silence risk on TeXML Play).
  if (!ivrOssPlayEnabled() && isIvrOssMediaPath(raw)) return "";
  if (/^https?:\/\//i.test(raw)) return raw;
  const base = origin.replace(/\/$/, "") || publicAppOrigin();
  return raw.startsWith("/") ? `${base}${raw}` : `${base}/${raw}`;
}

/**
 * Bridge disclosure+connecting clip.
 * Piper OSS defaults only apply when {@link ivrOssPlayEnabled}; otherwise TTS speaks.
 */
export function resolveBridgePromptAudioUrl(
  lang: IvrOssLang,
  configuredEn?: string | null,
  configuredAr?: string | null,
): string {
  const configured =
    lang === "ar" ? (configuredAr ?? "").trim() : (configuredEn ?? "").trim();
  if (configured) return resolvePublicMediaUrl(configured);
  if (!ivrOssPlayEnabled()) return "";
  const fallback = lang === "ar" ? DEFAULT_IVR_OSS_BRIDGE_AR : DEFAULT_IVR_OSS_BRIDGE_EN;
  return resolvePublicMediaUrl(fallback);
}

/**
 * Pick the OSS clip for a menu/start node from label / greeting hints.
 * Used when the saved graph has no audioUrl* yet (legacy templates).
 */
export function defaultOssAudioForNodeLabel(
  label: string | undefined,
  lang: IvrOssLang,
): string {
  const l = (label ?? "").toLowerCase();
  if (/lang|لغة|language|start|greeting|ترحيب/.test(l)) {
    return ivrOssPromptPath("language-menu", lang);
  }
  if (/center|centers|مركز|المراكز/.test(l)) {
    return ivrOssPromptPath("center-menu", lang);
  }
  if (/service|services|خدم/.test(l)) {
    return ivrOssPromptPath("service-menu", lang);
  }
  return "";
}
